import sys
from collections import defaultdict

def main():
    graph = defaultdict(list)
    all_tasks = set()

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        task, *deps = line.split(':')
        task = task.strip()
        deps = [d.strip() for d in deps]
        graph[task].extend(deps)
        all_tasks.add(task)

    done = set()
    order = []

    def visit(task):
        if task in done:
            return
        done.add(task)
        for dependency in sorted(graph[task]):
            visit(dependency)
        order.append(task)

    for task in sorted(all_tasks):
        if task not in done:
            visit(task)

    if len(order) == len(all_tasks):
        for task in order:
            print(task)
    else:
        remaining = sorted(all_tasks - done)
        print(f"CYCLE: {' '.join(remaining)}")


if __name__ == "__main__":
    main()
